import { selectVisible } from "./repository.mjs";
import { MAX_PAGE_SIZE } from "./limits.mjs";
export function listPage(records, {after=null,limit=2}={}) {
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_PAGE_SIZE) {
    throw new RangeError("Invalid page size");
  }
  const visible = selectVisible(records);
  let start = 0;
  if (after !== null) {
    if (typeof after !== "string") throw new RangeError("Invalid cursor");
    const index = visible.findIndex(row => row.id === after);
    if (index === -1) throw new RangeError("Invalid cursor");
    start = index + 1;
  }
  const items = visible.slice(start, start + limit);
  return {items, nextCursor: start + items.length < visible.length ? items.at(-1).id : null};
}

